    #[test]
    fn inactive_room_direct_video_offer_replays_card_and_ticket() {
        let (runtime, mut app, _local, peer) = build_join_request_test_app();
        let _guard = runtime.enter();
        vr_seed_friend(&mut app, peer, "Video sender");
        let topic = direct_topic(&app.local_public, &peer);
        let other = TopicId::from_bytes([9u8; 32]);
        app.topic = other;
        app.screen = Screen::Chat { topic: other };
        let offer_id = FileOfferId::generate();
        let hash = iroh_blobs::Hash::new(b"background video regression");
        let ticket = BlobTicket::new(
            iroh::EndpointAddr::new(peer),
            hash,
            iroh_blobs::BlobFormat::Raw,
        )
        .to_string();
        let messages = [
            Message::file_offer(offer_id, "background-video.mp4".into(), 1234).unwrap(),
            Message::FileOfferReady {
                offer_id,
                ticket: ticket.clone(),
                thumbnail_hash: None,
            },
        ];
        for message in messages {
            let _task = app.update(AppMessage::NetEvent(ConversationNetEvent::new(
                topic,
                NetEvent::Message {
                    from: peer,
                    message,
                    sent_at: SystemTime::now()
                        .duration_since(UNIX_EPOCH)
                        .unwrap()
                        .as_secs(),
                    backfilled: false,
                },
            )));
        }
        let conv = app.conversations.get(&topic).unwrap();
        assert_eq!(
            conv.pending_events.len(),
            2,
            "offer and ticket must survive background routing"
        );
        assert_eq!(conv.unread, 1, "ticket upgrades are not new attachments");
        assert!(app.switch_to_conversation(topic));
        let _task = app.replay_pending_events_batch(topic);
        let cards: Vec<_> = app
            .entries
            .iter()
            .filter_map(|entry| entry.download.as_ref())
            .collect();
        assert_eq!(cards.len(), 1, "replay creates exactly one attachment card");
        let card = cards[0];
        assert_eq!(card.direct_offer_key, Some((peer, offer_id)));
        assert_eq!(card.ticket, ticket);
        assert_eq!(card.expected_content_hash, Some(hash.to_string()));
        assert!(matches!(
            card.state,
            DownloadState::Ready { total: Some(1234) }
        ));
        assert!(matches!(
            card.availability,
            AttachmentAvailability::Hybrid { .. }
        ));
        assert!(app
            .entries
            .iter()
            .any(|entry| entry.body.contains("background-video.mp4")));
        // The card and ticket must also survive another conversation switch.
        assert!(app.switch_to_conversation(other));
        assert!(app.switch_to_conversation(topic));
        assert_eq!(
            app.entries
                .iter()
                .filter(|entry| entry.download.is_some())
                .count(),
            1
        );
    }

    #[test]
    fn direct_offer_history_restores_sender_receiver_and_missing_file() {
        let (runtime, app, _, _) = build_join_request_test_app();
        let _guard = runtime.enter();
        let remote = iroh::SecretKey::generate();
        for key in [app.secret_key.clone(), remote] {
            let topic = TopicId::from_bytes([42; 32]);
            let owner = key.public();
            let offer_id = FileOfferId::generate();
            let name = "history-video.mp4";
            let local_path = app.data_dir.join(name);
            std::fs::write(&local_path, b"video").unwrap();
            let hash = iroh_blobs::Hash::new(b"video");
            let ticket = BlobTicket::new(
                iroh::EndpointAddr::new(owner),
                hash,
                iroh_blobs::BlobFormat::Raw,
            )
            .to_string();
            let offer = SignedMessage::sign_and_encode(
                &key,
                &Message::file_offer(offer_id, name.into(), 5).unwrap(),
            )
            .unwrap();
            let ready = SignedMessage::sign_and_encode(
                &key,
                &Message::FileOfferReady {
                    offer_id,
                    ticket: ticket.clone(),
                    thumbnail_hash: Some([3; 32]),
                },
            )
            .unwrap();
            let store = MessageStore::open(&app.data_dir.join("message_store.db")).unwrap();
            store
                .persist_direct_offer(topic.as_bytes(), &offer, app.local_public.as_bytes(), None)
                .unwrap();
            store
                .persist_direct_offer(topic.as_bytes(), &ready, app.local_public.as_bytes(), None)
                .unwrap();
            store
                .set_direct_offer_local_path(
                    topic.as_bytes(),
                    owner.as_bytes(),
                    offer_id,
                    &local_path,
                )
                .unwrap();
            let rows = store
                .get_messages_for_topic(topic.as_bytes(), 100, 0)
                .unwrap();
            let row = rows.iter().find(|r| r.sender == *owner.as_bytes()).unwrap();
            drop(store);
            // Reopen SQLite from the exact production restore path, without
            // depending on the pending event queue or in-memory file registry.
            let entry = app.direct_offer_row_to_chat_entry(row).unwrap();
            let dl = entry.download.unwrap();
            assert_eq!(dl.name, name);
            assert_eq!(dl.ticket, ticket);
            assert_eq!(dl.direct_offer_key, Some((owner, offer_id)));
            assert_eq!(dl.thumbnail_hash, Some([3; 32]));
            assert_eq!(dl.expected_content_hash, Some(hash.to_string()));
            if owner == app.local_public {
                assert!(matches!(dl.state, DownloadState::Shared { .. }));
            } else {
                assert!(matches!(
                    dl.state,
                    DownloadState::Completed {
                        saved_path: Some(_),
                        ..
                    }
                ));
            }
            std::fs::remove_file(&local_path).unwrap();
            assert!(matches!(
                app.direct_offer_row_to_chat_entry(row)
                    .unwrap()
                    .download
                    .unwrap()
                    .state,
                DownloadState::Ready { .. }
            ));
        }
    }

    #[test]
    fn inactive_direct_offer_is_durable_before_opening_chat() {
        let (runtime, mut app, _, _) = build_join_request_test_app();
        let _guard = runtime.enter();
        let key = iroh::SecretKey::generate();
        let peer = key.public();
        vr_seed_friend(&mut app, peer, "Persistent sender");
        let topic = direct_topic(&app.local_public, &peer);
        app.topic = TopicId::from_bytes([9;32]);
        app.screen = Screen::ChatList;
        let id = FileOfferId::generate();
        let ticket = BlobTicket::new(iroh::EndpointAddr::new(peer), iroh_blobs::Hash::new(b"video"), iroh_blobs::BlobFormat::Raw).to_string();
        for message in [Message::file_offer(id, "inactive-history.mp4".into(), 5).unwrap(),
            Message::FileOfferReady { offer_id: id, ticket: ticket.clone(), thumbnail_hash: None }] {
            let signed = SignedMessage::sign_and_encode(&key, &message).unwrap();
            let (_, _, sent_at) = SignedMessage::verify_and_decode(&signed).unwrap();
            boru_core::chat_core::remember_signed_message(peer, &message, sent_at, &signed);
            let _task = app.update(AppMessage::NetEvent(ConversationNetEvent::new(topic,
                NetEvent::Message { from: peer, message, sent_at, backfilled: false })));
        }
        let store = MessageStore::open(&app.data_dir.join("message_store.db")).unwrap();
        let rows = store.get_messages_for_topic(topic.as_bytes(), 100, 0).unwrap();
        assert_eq!(rows.len(), 1, "inactive offers must survive without replay");
        app.conversations.clear();
        app.entries.clear();
        let entry = app.direct_offer_row_to_chat_entry(&rows[0]).unwrap();
        assert_eq!(entry.download.unwrap().ticket, ticket);
    }

    #[test]
    fn inactive_room_gossip_events_do_not_increment_unread() {
        let (_runtime, mut app, _local, peer) = build_join_request_test_app();
        let topic = direct_topic(&app.local_public, &peer);
        app.topic = TopicId::from_bytes([9u8; 32]);
        app.screen = Screen::Chat { topic: app.topic };

        // NeighborUp is pure gossip — no badge bump.
        let _t1 = app.update(AppMessage::NetEvent(ConversationNetEvent::new(
            topic,
            NetEvent::NeighborUp { peer },
        )));
        // Presence heartbeats are protocol noise — no badge bump.
        let _t2 = app.update(AppMessage::NetEvent(ConversationNetEvent::new(
            topic,
            NetEvent::Message {
                from: peer,
                message: Message::Presence,
                sent_at: 0,
                backfilled: false,
            },
        )));

        let conv = app.conversations.get(&topic).unwrap();
        assert_eq!(
            conv.unread, 0,
            "gossip protocol events never bump the unread badge"
        );
        assert_eq!(
            conv.pending_events.len(),
            0,
            "gossip protocol events are dropped, not queued (31cc58ac flood fix)"
        );
    }

    #[test]
    fn opening_conversation_clears_unread_badge_but_keeps_backlog() {
        let (_runtime, mut app, _local, peer) = build_join_request_test_app();
        let topic = direct_topic(&app.local_public, &peer);
        let other = TopicId::from_bytes([9u8; 32]);

        // A hidden conversation with a badge and a queued backlog.
        let mut conv = ConversationLive::new(topic);
        conv.unread = 3;
        conv.pending_events.push_back(NetEvent::Message {
            from: peer,
            message: Message::Message {
                text: "queued 1".into(),
            },
            sent_at: 1,
            backfilled: false,
        });
        conv.pending_events.push_back(NetEvent::Message {
            from: peer,
            message: Message::Message {
                text: "queued 2".into(),
            },
            sent_at: 2,
            backfilled: false,
        });
        app.conversations.insert(topic, conv);

        // A different room is active; opening the hidden conversation clears
        // its badge (sidebar unread anchor) while the backlog stays queued
        // for incremental replay.
        app.topic = other;
        app.screen = Screen::Chat { topic: other };
        assert!(app.switch_to_conversation(topic), "switch to backlog room");

        let restored = app
            .conversations
            .get(&topic)
            .expect("backlog conversation retained in map");
        assert_eq!(restored.unread, 0, "viewing clears the unread badge");
        assert_eq!(
            restored.pending_events.len(),
            2,
            "queued backlog is retained for replay after the badge clears"
        );
    }

    // ═════════════════════════════════════════════════════════════════
    // UI-RESTYLE-11 follow-up — PERMANENT regression harness for the
    // three creation flows (Create Group Chat / Create Public Room /
    // Create Tunnel).
    //
    // Refactored from the original UI-RESTYLE-11 temporary harness to
    // assert on OBSERVABLE OUTCOMES wherever possible:
    //   • system messages (entries with ChatKind::System)
    //   • toasts (toast_message)
    //   • store entries (conversation_store / shared_tunnels)
    //   • screen/dialog flags (show_*_dialog, share_local_service_open,
    //     room_loading)
    //   • rendered view (app.view() smoke-render)
    //
    // Remaining internal-state assertions (text-input values, member
    // selection set, expiry picker) are INTENTIONAL: iced's Element tree
    // is not introspectable in a headless test, so typed text and
    // selection state have no observable proxy other than the state that
    // renders them. Each such assertion is marked "intentional state".
    //
    // NOTE (UI-RESTYLE-07 drift): the Create Group Chat dialog no longer
    // has a search/filter field (removed during the dialog restyle), so
    // the original harness's CreateGroupSearchChanged coverage is
    // obsolete; name + description + member toggle coverage is retained.
    // ═════════════════════════════════════════════════════════════════

    fn vr_seed_friend(app: &mut IcedChat, peer: PublicKey, label: &str) {
        use boru_core::friends::{FriendId, FriendRecord, FriendRelationship};
        app.friends.upsert(
            FriendId::from_public_key(peer),
            FriendRecord {
                label: Some(label.to_string()),
                relationship: FriendRelationship::Friends,
                ..Default::default()
            },
        );
    }

    fn vr_system_bodies(app: &IcedChat) -> Vec<String> {
        app.entries
            .iter()
            .filter(|e| matches!(e.kind, ChatKind::System))
            .map(|e| e.body.clone())
            .collect()
    }

    #[test]
    fn vr_create_group_chat_opens_renders_and_accepts_input() {
        let (_runtime, mut app, _local, peer) = build_join_request_test_app();
        vr_seed_friend(&mut app, peer, "Bob");

        // Observable: the dialog opens (screen/dialog flag).
        assert!(!app.show_create_group_dialog);
        let _ = app.update(AppMessage::ShowCreateGroupDialog);
        assert!(
            app.show_create_group_dialog,
            "dialog opens (observable flag)"
        );
        let _ = app.view(); // renders without panic

        // Intentional state: name/description inputs hold typed text; no
        // observable proxy exists in a headless test.
        let _ = app.update(AppMessage::CreateGroupNameChanged("Weekend Plans".into()));
        let _ = app.update(AppMessage::CreateGroupDescriptionChanged(
            "Beach trip".into(),
        ));
        assert_eq!(app.create_group_name, "Weekend Plans");
        assert_eq!(app.create_group_description, "Beach trip");

        // Intentional state: member selection set renders as checkboxes in
        // view(); toggle selects then deselects.
        let _ = app.update(AppMessage::CreateGroupMemberToggled(peer));
        assert!(
            app.create_group_selected_members.contains(&peer),
            "peer selectable and toggle selects it"
        );
        let _ = app.view(); // renders chip + selected row without panic

        let _ = app.update(AppMessage::CreateGroupMemberToggled(peer));
        assert!(
            app.create_group_selected_members.is_empty(),
            "toggle deselects"
        );
        let _ = app.view();
    }

    #[test]
    fn vr_create_group_chat_confirm_cancel_and_validation() {
        let (_runtime, mut app, _local, peer) = build_join_request_test_app();
        vr_seed_friend(&mut app, peer, "Bob");

        // Observable: cancel closes the dialog (screen/dialog flag).
        let _ = app.update(AppMessage::ShowCreateGroupDialog);
        assert!(app.show_create_group_dialog);
        let _ = app.update(AppMessage::HideCreateGroupDialog);
        assert!(!app.show_create_group_dialog);

        // Observable: empty-name confirm surfaces a SYSTEM MESSAGE and the
        // dialog stays open; no async creation starts (room_loading flag
        // stays false).
        let _ = app.update(AppMessage::ShowCreateGroupDialog);
        let _ = app.update(AppMessage::ConfirmCreateGroup);
        assert!(
            vr_system_bodies(&app).contains(&"Group name is required.".to_string()),
            "system message surfaces for empty group name"
        );
        assert!(
            app.show_create_group_dialog,
            "dialog stays open on invalid submit"
        );
        assert!(!app.room_loading, "no async creation started");

        // Observable: named confirm raises the submit loading flag and
        // room_loading (async creation in flight); post UI-RESTYLE-07 the
        // dialog stays open with a loading state rather than closing
        // immediately.
        let _ = app.update(AppMessage::CreateGroupNameChanged("Weekend Plans".into()));
        let _ = app.update(AppMessage::ConfirmCreateGroup);
        assert!(
            app.create_group_submitting,
            "submit loading flag raised on valid submit"
        );
        assert!(app.room_loading, "creation loading flag set");
        assert!(
            app.show_create_group_dialog,
            "dialog stays open while submitting"
        );
        let _ = app.view(); // renders loading state without panic
    }

